/**
 * Docs Module – Document Library with localStorage cache
 * 
 * Features:
 * - Uses localStorage as primary cache
 * - Loads /data/docs/manifest.json first (generated by build)
 * - Falls back to manifest-core.json if manifest.json is not found
 * - Dynamically discovers HTML files in /data/docs/ and subdirectories
 * - Documents organized by type: core, resources, adventures, expansions, etc.
 * - Uploader with type dropdown
 * - Document viewer with sanitized content
 * - Clean path resolution
 */

import { escHtml } from '../../core/utils.js';
import { showToast } from '../../components/Toast.js';

// ============================================================
// CONSTANTS
// ============================================================

const DOCS_BASE_PATH = '/data/docs/';
const MANIFEST_PATH = '/data/docs/manifest.json';           // primary manifest (generated)
const MANIFEST_CORE_PATH = '/data/docs/manifest-core.json'; // fallback manifest
const CACHE_KEY = 'fates-edge-docs-cache';
const CACHE_TTL = 3600000; // 1 hour

// ─── Document Types (from build_config.toml) ────────────────
const DOC_TYPES = {
    core: {
        label: '📘 Core',
        folder: 'core',
        icon: '📘',
        description: 'Core rulebooks and essential documents'
    },
    resources: {
        label: '📚 Resources',
        folder: 'resources',
        icon: '📚',
        description: 'Reference guides, character sheets, and GM aids'
    },
    adventures: {
        label: '🗡️ Adventures',
        folder: 'adventures',
        icon: '🗡️',
        description: 'Pre-written adventures and campaigns'
    },
    expansions: {
        label: '📦 Expansions',
        folder: 'expansions',
        icon: '📦',
        description: 'Expansion content and supplementary rules'
    },
    travel: {
        label: '🗺️ Travel',
        folder: 'travel',
        icon: '🗺️',
        description: 'World guides, regional information, and travel content'
    },
    design: {
        label: '🎨 Design',
        folder: 'design',
        icon: '🎨',
        description: 'Game design documents and development notes'
    },
    konreh: {
        label: '♟️ Kon\'reh',
        folder: 'konreh',
        icon: '♟️',
        description: 'Kon\'reh strategy game content'
    },
    quickstart: {
        label: '⚡ Quickstart',
        folder: 'quickstart',
        icon: '⚡',
        description: 'One-page quickstart guides for new players'
    },
    uploaded: {
        label: '📤 Uploaded',
        folder: 'uploaded',
        icon: '📤',
        description: 'User-uploaded documents'
    },
    other: {
        label: '📄 Other',
        folder: 'other',
        icon: '📄',
        description: 'Miscellaneous documents'
    }
};

// Reverse map: folder -> type id
const FOLDER_TO_TYPE = {};
for (const [id, type] of Object.entries(DOC_TYPES)) {
    FOLDER_TO_TYPE[type.folder] = id;
}

// ─── Type order for sorting ──────────────────────────────────
const TYPE_ORDER = ['core', 'quickstart', 'resources', 'adventures', 'expansions', 'travel', 'design', 'konreh', 'uploaded', 'other'];

// ============================================================
// STATE
// ============================================================

let allDocs = [];
let currentDocPath = null;
let isDarkMode = false;
let container = null;

// ============================================================
// HELPERS
// ============================================================

function getDocTitle(file) {
    return file
        .replace(/\.html$/, '')
        .replace(/Fates_-_Edge_-_-/g, '')
        .replace(/_/g, ' ')
        .replace(/-/g, ' ')
        .replace(/\b\w/g, l => l.toUpperCase())
        .trim();
}

function getDocTypeFromFile(file) {
  const adventurePatterns = ['Saga', 'Dreams', 'Serpent', 'Blood', 'Carnival', 'Adventure', 'Coil', 'Lantern'];
  if (adventurePatterns.some(p => file.includes(p))) return 'adventures';
  if (file.includes('Screen') || file.includes('GM')) return 'resources';
  if (file.includes('Reference') || file.includes('SRD') || file.includes('Essentials') || file.includes('Essential')) return 'core';
  return 'other';
}

function resolveFullPath(doc) {
    if (!doc) return null;
    if (doc.fullPath) return doc.fullPath;

    if (doc.file) {
        const file = doc.file.replace(/^\/+|\/+$/g, '');
        let folder = doc.folder || '';
        if (doc.type && DOC_TYPES[doc.type]) {
            folder = DOC_TYPES[doc.type].folder;
        }
        if (!folder || folder === 'core') {
            return DOCS_BASE_PATH + file;
        }
        return DOCS_BASE_PATH + folder + '/' + file;
    }
    return null;
}

function normalizeFileName(file) {
    if (!file) return file;
    return file.trim().replace(/^\/+|\/+$/g, '').replace(/\s+/g, ' ');
}

function docsAreSame(docA, docB) {
    if (!docA || !docB) return false;
    if (docA.fullPath && docB.fullPath) {
        return docA.fullPath === docB.fullPath;
    }
    if (docA.file && docB.file) {
        return normalizeFileName(docA.file) === normalizeFileName(docB.file);
    }
    return false;
}

// FIX: this used to flag any document containing the loose prose phrase
// "Fate's Edge Toolkit" as "the SPA shell, not a real document" -- but
// several real documents (like the Kon'reh Definitive Guide, whose own
// subtitle reads "Fate's Edge Toolkit Edition") legitimately contain that
// phrase in their own text. That false positive is what caused the
// "server returned SPA" error when opening the guide from inside the
// app, even though the raw file loads fine when navigated to directly
// (which bypasses this check entirely). Detection now only looks for
// markers that are actually structural/unique to index.html itself --
// the module entry-point script tag and the toast-container div that
// only the app shell has -- not phrases that can legitimately appear in
// a document's own prose.
function isSpaContent(html) {
    if (!html) return false;
    const spaIndicators = [
        '<script type="module" src="js/app.js">',
        'id="toast-container"',
        '<div id="app">'
    ];
    return spaIndicators.some(indicator => html.includes(indicator));
}

function sanitizeHtml(html) {
    let sanitized = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
    sanitized = sanitized.replace(/<base[^>]*>/gi, '');
    const bodyMatch = sanitized.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    if (bodyMatch) {
        sanitized = bodyMatch[1];
    }
    return sanitized;
}

function getDocType(doc) {
    if (doc.type && DOC_TYPES[doc.type]) return doc.type;
    if (doc.folder && FOLDER_TO_TYPE[doc.folder]) return FOLDER_TO_TYPE[doc.folder];
    if (doc.fullPath) {
        const pathParts = doc.fullPath.split('/');
        for (const part of pathParts) {
            if (FOLDER_TO_TYPE[part]) return FOLDER_TO_TYPE[part];
        }
    }
    if (doc.file) {
        return getDocTypeFromFile(doc.file);
    }
    return 'other';
}

function getTypeLabel(typeId) {
    return DOC_TYPES[typeId]?.label || DOC_TYPES.other.label;
}

function getTypeIcon(typeId) {
    return DOC_TYPES[typeId]?.icon || DOC_TYPES.other.icon;
}

function getTypeClass(typeId) {
    return typeId || 'other';
}

// ============================================================
// RENDER
// ============================================================

